<template>
  <section class="lol-live-records" :aria-label="copy.title" @keydown.esc="clearTracking">
    <div class="phase-tools">
      <div class="phase-tabs" role="group" :aria-label="copy.phase"><button v-for="phase in phases" :key="phase.key" type="button" :aria-pressed="current?.key === phase.key" @click="selected=phase.key;clearTracking()">{{ isChinese ? phase.label : phase.enLabel }}</button></div>
      <button v-if="activeTeam" type="button" class="clear-tracking" @click="clearTracking">{{ activeTeam }} × <span class="sr-only">{{ copy.clear }}</span></button>
    </div>
    <div class="stage-context"><span>{{ phaseNote }}</span><span :title="copy.tracking">{{ copy.trackHint }}</span></div>
    <p v-if="loading && !current" role="status">{{ copy.loading }}</p>
    <div v-if="current" class="record-body" :key="current.key" tabindex="0" :aria-label="`${isChinese ? current.label : current.enLabel} · ${copy.results}`">
      <template v-if="current.key === 'playoffs'">
        <p class="playoff-hint">{{ copy.bracketHint }}</p>
        <div class="playoff-scroll" tabindex="0" :aria-label="copy.bracket">
          <div class="playoff-head"><h3 v-for="heading in copy.bracketHeadings" :key="heading">{{ heading }}</h3></div>
          <div class="playoff-tree" :style="{height:playoffLayout.height+'px','--playoff-row':playoffLayout.rowHeight+'px'}">
            <svg class="playoff-connections" :viewBox="`0 0 1000 ${playoffLayout.height}`" preserveAspectRatio="none" aria-hidden="true"><path v-for="edge in playoffLayout.edges" :key="edge.from" :d="edge.path" :class="{'is-tracked': teamPath.edges.has(`${edge.from}>${edge.to}:${edge.slot}`)}" /></svg>
            <section v-for="round in playoffLayout.rounds" :key="round.column" class="playoff-column">
              <LolOfficialMatch v-for="node in round.matches" :key="node.match.id" :style="{gridRow:`${node.start} / span ${node.span}`}" :match="node.match" :chinese="isChinese" :tracked="tracked" :pinned="activeTeam" :highlighted="Boolean(tracked && teamPath.ids.has(node.match.structuralId))" :knockout="true" :pending-labels="pendingLabels(node.match)" :highlighted-slots="[1,2].filter(slot=>teamPath.slots.has(`${node.match.structuralId}:${slot}`))" @hover="hovered=$event" @focus="focused=$event" @pin="pinTeam" />
            </section>
          </div>
        </div>
      </template>
      <template v-else>
        <div v-if="current.key === 'swiss' && current.teams.length" class="record-cohorts">
          <section v-for="group in recordGroups" :key="group.record"><h3>{{ group.record }} <span>{{ group.teams.length }} {{ isChinese ? '队' : 'teams' }}</span></h3><div class="cohort-teams"><button v-for="entry in group.teams" :key="entry.code" type="button" :aria-pressed="activeTeam===entry.code" :title="entry.name" :class="teamClass(entry.code)" @mouseenter="hovered=entry.code" @mouseleave="hovered=''" @focus="focused=entry.code" @blur="focused=''" @click="pinTeam(entry.code)"><img v-if="entry.image" :src="entry.image" alt="" loading="lazy"/><strong>{{ entry.code }}</strong></button></div></section>
        </div>
        <div v-else-if="current.key==='round4' && current.teams.length" class="record-table-wrap"><table><caption class="sr-only">{{ isChinese ? current.label : current.enLabel }}</caption><thead><tr><th>{{ copy.team }}</th><th>{{ copy.wins }}</th><th>{{ copy.losses }}</th><th>{{ copy.record }}</th></tr></thead><tbody><tr v-for="entry in current.teams" :key="entry.code" :class="teamClass(entry.code)"><th scope="row"><button type="button" :aria-pressed="activeTeam===entry.code" :title="entry.name" @mouseenter="hovered=entry.code" @mouseleave="hovered=''" @focus="focused=entry.code" @blur="focused=''" @click="pinTeam(entry.code)"><img v-if="entry.image" :src="entry.image" alt="" loading="lazy"/><strong>{{ entry.code }}</strong><span>{{ entry.name }}</span></button></th><td class="record-wins">{{ entry.wins }}</td><td>{{ entry.losses }}</td><td class="record-value">{{ entry.wins }}–{{ entry.losses }}</td></tr></tbody></table></div>
        <div v-if="rounds.length" class="record-rounds" :class="{'is-qualification':current.key==='round5'}">
          <section v-for="round in rounds" :key="round.key"><h3>{{ current.key==='round5' ? copy.qualification : `${copy.round} ${round.key}${isChinese ? ' 轮' : ''}` }}</h3><LolOfficialMatch v-for="match in round.matches" :key="match.id" :match="match" :chinese="isChinese" :tracked="tracked" :pinned="activeTeam" :highlighted="Boolean(tracked && match.teams.some(t=>t.code===tracked))" :qualification="current.key==='round5'" @hover="hovered=$event" @focus="focused=$event" @pin="pinTeam" /></section>
        </div>
        <p v-else-if="!current.teams.length">{{ copy.pending }}</p>
      </template>
    </div>
    <footer><span v-if="snapshot?.updateTime">{{ copy.checked }} {{ checkedTime }}</span><a v-if="current" :href="current.url" target="_blank" rel="noopener noreferrer">{{ copy.official }} ↗</a><span v-if="error || snapshot?.degraded?.length" role="status">{{ copy.partial }}</span></footer>
  </section>
</template>
<script setup>
import {computed,onBeforeUnmount,onMounted,ref,watch} from 'vue';
import LolOfficialMatch from '@/components/LolOfficialMatch.vue';
import {officialMatchLabel,officialPlayoffLayout,officialTeamPath} from '@/utils/lolPhaseLayout.js';
const props=defineProps({locale:{type:String,default:'zh-CN'},date:String,refreshKey:[String,Number],fallbackEntries:{type:Array,default:()=>[]}});
const emit=defineEmits(['stage-url']);
const snapshot=ref(null),selected=ref(''),loading=ref(false),error=ref(false),activeTeam=ref(''),hovered=ref(''),focused=ref('');
let request=0,controller;
const isChinese=computed(()=>props.locale.startsWith('zh'));
const copy=computed(()=>isChinese.value?{title:'德杯官方阶段赛果',phase:'官方阶段',clear:'清除追踪',trackHint:'悬浮追踪 · 点击固定',tracking:'悬浮或键盘聚焦可追踪队伍；点击固定，Esc清除。日期只筛选右侧赛程。',loading:'正在核对官方赛果…',team:'战队',wins:'系列胜',losses:'系列负',record:'本阶段战绩',round:'第',qualification:'晋级对决 · BO3',pending:'待开赛',checked:'核对于',official:'官方阶段赛果',results:'完整赛果',partial:'部分官方阶段暂不可读，请查看原始赛果。',bracket:'淘汰赛晋级对阵，可横向滚动',bracketHint:'对阵已公布；虚线格为前一轮胜者，尚未开赛的比分不显示。',bracketHeadings:['1/4 决赛','半决赛','决赛']}:{title:'Official DCGI stage results',phase:'Official stages',clear:'Clear tracking',trackHint:'Hover to trace · Click to pin',tracking:'Hover or focus a team; click to pin, Escape to clear. Date filters the schedule only.',loading:'Checking official results…',team:'Team',wins:'Series W',losses:'Series L',record:'Stage record',round:'Round',qualification:'Qualification · BO3',pending:'Upcoming',checked:'Checked',official:'Official stage results',results:'Full results',partial:'Some official stages are unavailable. Check the original results.',bracket:'Playoff bracket, scroll horizontally',bracketHint:'Announced pairings. Pending slots show the previous-round winner; no scores before play.',bracketHeadings:['Quarterfinals','Semifinals','Final']});
const phaseNote=computed(()=>isChinese.value?({swiss:'同战绩重新配对 · 以下为已确认的各轮赛果',round4:'循环赛 · 本阶段系列胜负，不计入初始瑞士轮',round5:'最后晋级赛 · 胜者进入线下淘汰赛',playoffs:'线下单败淘汰 · 全程 BO5'}[current.value?.key]||'最近可用的阶段赛果'):({swiss:'Re-paired by record · Confirmed round results',round4:'Round robin · Stage series records, separate from Swiss',round5:'Final qualification · Winners advance to playoffs',playoffs:'Offline single elimination · BO5'}[current.value?.key]||'Last available stage results'));
const fallback=computed(()=>({key:'swiss',label:'初始瑞士轮 · 最近可用',enLabel:'Initial Swiss · last available',url:'https://lolesports.com/en-US/results/117133773242499009/stage/117133805551803623',matches:[],teams:props.fallbackEntries.flatMap(e=>{const m=/^(\d+)-(\d+)$/.exec(e.record||'');return m?[{...e,wins:Number(m[1]),losses:Number(m[2])}]:[]})}));
const phases=computed(()=>snapshot.value?.phases || (fallback.value.teams.length?[fallback.value]:[])),current=computed(()=>phases.value.find(p=>p.key===selected.value)||phases.value[0]);
watch(()=>current.value?.url,url=>{if(url)emit('stage-url',url)},{immediate:true});
const rounds=computed(()=>{const groups=new Map();for(const m of current.value?.matches||[]){const key=/^R(\d+)/.exec(m.description)?.[1]||'–';if(!groups.has(key))groups.set(key,[]);groups.get(key).push(m)}return [...groups].map(([key,matches])=>({key,matches}))});
const recordGroups=computed(()=>{const map=new Map();for(const entry of current.value?.teams||[]){const record=entry.wins+'–'+entry.losses;if(!map.has(record))map.set(record,[]);map.get(record).push(entry)}return [...map].map(([record,teams])=>({record,teams}))});
const clearTracking=()=>{activeTeam.value='';hovered.value='';focused.value=''};
const pinTeam=code=>{hovered.value='';focused.value='';activeTeam.value=activeTeam.value===code?'':code};
const tracked=computed(()=>hovered.value||focused.value||activeTeam.value);
const teamClass=code=>({'is-active':tracked.value===code,'is-muted':Boolean(tracked.value && tracked.value!==code)});
const playoffLayout=computed(()=>officialPlayoffLayout(current.value?.matches||[]));
const teamPath=computed(()=>officialTeamPath(current.value?.matches||[],tracked.value));
const pendingLabels=match=>match.teams.map((_,index)=>{const from=current.value.matches.find(m=>m.next?.structuralId===match.structuralId&&m.next.slot===index+1);return from ? officialMatchLabel(from,isChinese.value)+(isChinese.value?' 胜者':' winner') : ''});
const checkedTime=computed(()=>new Intl.DateTimeFormat(props.locale,{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date(snapshot.value.updateTime)));
const load=async()=>{const version=++request;controller?.abort();controller=new AbortController();loading.value=true;try{const r=await fetch('/api/lol-event-snapshot?event=demacia-cup-2026',{signal:controller.signal});const data=await r.json();if(!r.ok||data.code!==200)throw Error('unavailable');if(version!==request)return;snapshot.value=data;error.value=false;if(!selected.value)selected.value=data.phases.at(-1)?.key||'swiss';}catch{if(version===request)error.value=true}finally{if(version===request)loading.value=false}};
watch(()=>props.refreshKey,load);onMounted(load);onBeforeUnmount(()=>{request++;controller?.abort()});
</script>
<style scoped>
