:global(.event-hub.is-dark .lol-live-records){--records-muted:#a0a5ad;--records-accent:var(--lol-trace-accent,#b7c1ff);--records-win:var(--lol-result-win,#8ac6af);--records-loss:var(--lol-result-loss,#e6a1a8);--records-gold:#dec682;--records-surface:#19191e}
