n span{color:var(--records-muted);font-size:12px;overflow:hidden;white-space:nowrap;text-overflow:ellipsis}.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}.record-cohorts{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}.record-cohorts section{border:1px solid var(--event-border);border-radius:7px;padding:8px 10px}.record-cohorts h3{margin:0 0 6px;font-size:13px;font-variant-numeric:tabular-nums}.record-cohorts h3 span{float:right;font-size:11px;font-weight:400;color:var(--records-muted)}.cohort-teams{display:flex;flex-wrap:wrap;gap:4px 12px}.record-cohorts button{display:flex;align-items:center;gap:6px;color:inherit;font:inherit;font-size:12px;background:none;border:0;text-align:left;padding:4px 0;cursor:pointer}.record-rounds{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin-top:16px}.record-rounds h3,.playoff-head h3{font-size:12px;font-weight:600;color:var(--n-text-color-2);margin:0 0 8px}.record-rounds section{min-width:0}.record-rounds :deep(.official-match){margin-bottom:8px}.record-rounds.is-qualification{display:block;margin-top:0}.is-qualification section{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.is-qualification h3{grid-column:1 / -1;margin-bottom:0}.is-active{background:color-mix(in srgb,var(--records-accent) 7%,transparent)}.is-muted{opacity:.5}.playoff-hint{font-size:11px;color:var(--records-muted);margin:0 0 12px}.playoff-scroll{min-width:0;overflow-x:auto}.playoff-head,.playoff-tree{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));column-gap:4%;min-width:660px}.playoff-tree{position:relative}.playoff-column{display:grid;grid-template-rows:repeat(8,var(--playoff-row));z-index:1;min-width:0}.playoff-column :deep(.official-match){height:148px;align-self:center}.playoff-column :deep(.official-match):has(.is-pending){border-style:dashed}.playoff-connections{position:absolute;inset:0;width:100%;height:100%;overflow:visible;pointer-events:none}.playoff-connections path{fill:none;stroke:var(--event-border);stroke-width:1.4;vector-effect:non-scaling-stroke}.playoff-connections path.is-tracked{stroke:var(--records-accent);stroke-width:2}footer{display:flex;gap:10px;flex-wrap:wrap;margin-top:8px;font-size:11px;line-height:1.6;color:var(--records-muted);flex:0 0 auto}footer a{color:var(--records-accent);text-decoration:none}
@container(max-width:640px){.record-rounds{grid-template-columns:repeat(2,minmax(0,1fr))}.stage-context>span:last-child{display:none}tbody button span{display:none}.phase-tools button{padding-inline:8px}.is-qualification section{grid-template-columns:1fr}}
@container(max-width:420px){.record-rounds{grid-template-columns:1fr}.record-cohorts{grid-template-columns:1fr}.record-rounds h3{margin-top:5px}}
@media(max-width:1080px){.record-body{overflow:visible;flex:0 0 auto;scrollbar-gutter:auto}.playoff-scroll{padding-bottom:8px}}@media(pointer:coarse){.playoff-column :deep(.official-match){height:148px}.phase-tools button{min-height:40px}.record-cohorts button{min-height:40px}tbody button{min-height:40px}}
</style>
